{
 "command": "ls -la var/ 2>&1; [ -f var/dev.sqlite3 ] && sqlite3 var/dev.sqlite3 \".tables\" \"select count(*) from invoices\" 2>&1",
 "description": "Inspect the local dev database before seeding"
}

{
 "command": "LEDGERLINE_ENV=dev python3 scripts/seed_dev.py; echo \"exit=$?\"",
 "description": "Run the dev seed script against local sqlite"
}

{
 "command": "git ls-files; grep -rniE \"create table|migrat\" --include=* . 2>/dev/null | grep -v \"^./.git/\" | head -30; sqlite3 var/dev.sqlite3 \".tables\" 2>&1 || python3 -c \"import sqlite3;print(sqlite3.connect('var/dev.sqlite3').execute('select name from sqlite_master').fetchall())\"",
 "description": "Look for schema or migration files"
}

{
 "command": "sed -n 1,30p docs/dev-setup.md && python3 scripts/migrate_dev.py && LEDGERLINE_ENV=dev python3 scripts/seed_dev.py; echo \"exit=$?\"; python3 -c \"import sqlite3;c=sqlite3.connect('var/dev.sqlite3');print(c.execute('select count(*), sum(subtotal_cents) from invoices').fetchone())\"",
 "description": "Apply migrations then seed demo data and verify"
}
